# -*- coding: utf-8 -*-
B=[
dict(a=1,z=2,star=3,
lit='「猶大的罪是用鐵筆、用金鋼石的尖刻上的，刻在他們的心版上和他們祭壇的角上；他們的兒女記念他們在青翠樹旁、高岡上的祭壇和亞舍拉。」',
key=[('鐵筆','H5842','be-et barzel','鐵筆'),('金鋼石','H8068','shamir','金鋼石（最硬的石）'),('刻','H2790','kharushah','刻上、犁'),('心版','H3871','luach libbam','心上的板'),('亞舍拉','H842','asherehem','木偶、亞舍拉'),('記念','H2142','kezekhor','記念')],
gram=['**{H8068}**（shamir，金鋼石）：這是**古代最硬的石頭**，用來切割其他石頭。「用金鋼石的尖刻」是說：**這個罪，不是塗鴉，而是刻進去的。**','**{H3871}**（luakh，板）：「心版」是對比**十誡的石版**（出三十一章十八節）：神把律法刻在石版上；現在，**罪被刻在心版上**。耶利米書三十一章三十三節的新約應許，就是神要把律法寫在**心版**上。'],
exp=['十七章一節是**整卷書最有力的畫面之一**：猶大的罪，是用鐵筆、用金鋼石的尖刻上的，刻在他們的心版上。金鋼石是古代最硬的石頭，用它刻出來的字，**擦不掉、磨不平**。這是一個很嚴肅的診斷：罪不只是行為，罪已經**刻進了人心**。','請把這節與三十一章三十三節對照：「我要將我的律法放在他們裡面，寫在他們心上」。**心版上已經有刻痕——是罪的刻痕**；神的應許，不是擦掉它，而是**寫上新的**。這就是**新約**的核心。','二節說「他們的兒女記念」：一代傳一代，偶像的祭壇**也被刻進了孩子的記憶**。我們傳給下一代的，不只是話，而是我們所**愛的、所敬拜的**。這是對所有父母的提醒。']),
dict(a=3,z=4,star=2,
lit='「我田野的山哪，我要因你在四境內的罪，把你的財物、一切寶物和你的邱壇當作掠物交出去；你要因自己的罪，失去我所賜給你的產業；我要使你在你所不認識的地上，服事你的仇敵，因為你們使我怒中起火，直燒到永遠。」',
key=[('失去','H8058','ushmatta','撒手、放棄'),('產業','H5159','minakhalatkha','產業、分'),('服事','H5647','vehaavadetikha','使你作奴僕'),('火','H784','esh','火'),('永遠','H5769','olam','永遠')],
gram=['**{H8058}**（shamat，撒手）：這個字在出埃及記二十三章十一節、申命記十五章一節，用於**安息年的「撒手」**：土地要歇息，債務要免除。現在，**百姓因為不守安息，連土地都要「撒手」了**（參看十七章十九至二十七節的安息日）。這是一個**很美的伏筆**。'],
exp=['三、四節接著說審判：財物被掠、產業失去、要在不認識的地上服事仇敵。這是**第一段的結論**：罪刻進了心，就**一定會結出果子**。這個果子是**失去**：失去財富，失去土地，失去自由。','請留意「失去」（shamat）這個字：它是安息年的用語——**地要「撒手」歇息**。他們一直不守安息年（利二十六章三十四至三十五節），結果神**用審判讓土地得到它應得的安息**。這是整章**安息日**主題（十九至二十七節）的**伏筆**。']),
dict(a=5,z=6,star=3,
lit='「耶和華這樣說：倚靠人、以血肉為膀臂、心卻離棄耶和華的人，是受咒詛的。他必像沙漠裡的杜松，看不見福樂來到，卻要住在曠野乾旱之處，無人居住的鹽鹼地。」',
key=[('受咒詛','H779','arur','受咒詛的'),('倚靠','H982','yivtakh','信靠、倚靠'),('血肉','H1320','basar','肉、血肉'),('杜松','H6176','ka-ar','杜松、荒漠灌木'),('鹽鹼地','H4420','melekhah','鹽地'),('離棄','H5493','yasur','轉離')],
gram=['**{H779}**（arur，受咒詛）：與下一節的「有福」（barukh）是**一對反義詞**，也是**申命記二十八章**「祝福與咒詛」的語言。耶利米把整個**摩西之約的框架**，濃縮成兩棵樹。','**{H982}**（batakh，倚靠）：這個字的本義是**把全身重量放在上面**。倚靠人，是把重量放在一個會倒的東西上。'],
exp=['五、六節是**一對鮮明的對比**的上半：倚靠人、以血肉為膀臂、心卻離棄耶和華的人，是受咒詛的。注意：這不是說**所有**倚靠人的事都是罪（我們每天都倚靠醫生、老師、朋友）。重點是**心離棄了神**，把**最終的倚靠**放在人身上。','他的下場是一個很具體的畫面：像沙漠裡的杜松，一種**矮小、乾枯的荒漠灌木**，看不見福樂來到，住在乾旱之處、無人居住的鹽鹼地。**一個把重量放在人身上的人，結果是一片荒漠**。','請記得：這不是對別人的咒詛，而是對**我們自己心的診斷**。**我最終倚靠的，是誰？**這是整卷書反覆問的問題。']),
dict(a=7,z=8,star=3,
lit='「倚靠耶和華、以耶和華為倚靠的人，是有福的。他必像樹栽在水旁，在河邊扎根，炎熱來到，並不懼怕，葉子仍然青翠；在乾旱之年毫無掛慮，而且結果不止。」',
key=[('有福','H1288','barukh','蒙福的'),('可靠','H4009','mivtakho','他所倚靠的'),('栽','H8362','shatul','栽種、移植'),('根','H8328','sharashav','根'),('青翠','H7488','raanan','青翠、茂盛'),('掛慮','H1672','yidag','憂慮'),('果子','H6529','peri','果子')],
gram=['**{H8362}**（shatul，栽）：這個字是**被「栽」在那裡**的，不是自己長出來的。蒙福的人，是**被神栽在水旁**的人。這與詩篇一篇三節是同一個畫面。','**{H1672}**（daag，憂慮）：「毫無掛慮」是 **daag** 的否定。這個字在撒上九章五節、詩篇三十八篇十八節出現，指**心裡的焦慮**。**這棵樹沒有焦慮**，不是因為它沒有乾旱，而是因為**它的根在水裡**。'],
exp=['七、八節是這一對對比的下半，也是**整章最美的一段**：倚靠耶和華的人，像樹栽在水旁，在河邊扎根，炎熱來到並不懼怕，葉子仍然青翠，乾旱之年毫無掛慮，結果不止。這是與詩篇一篇的**同一幅畫**，卻有一個**關鍵的不同**。','請看這個不同：**詩篇一篇的樹，是在「平安」中結果**；**耶利米的樹，是在「炎熱」與「乾旱」中結果**。耶利米書第十四章才剛寫完一場大旱，這裡的畫面是：**乾旱仍然來，可是這棵樹不懼怕、不掛慮**。它的秘訣不是沒有乾旱，而是**它的根在水裡**。','你的根在哪裡？你可以回想前一章（十六章十九節）的先知：他一無所有，卻說「你是我的力量」。**他就是這棵樹。**扎根，是一個**日復一日**的事：每天讀經、禱告、靠近神，**根就一寸一寸地往下**。']),
dict(a=9,z=9,star=3,
lit='「人心比萬物都詭詐，是無法醫治的；誰能識透呢？」',
key=[('詭詐','H6121','aqov','彎曲、狡詐'),('無法醫治','H605','anush','無法醫治、病重'),('心','H3820','halev','心'),('識透','H3045','yeddennu','認識、知道')],
gram=['**{H6121}**（aqov，彎曲）：這個字與**雅各**（Yaaqov）同字根：雅各的名字，本義是「抓腳跟的、欺騙者」（創二十五章二十六節；二十七章三十六節）。「人心 aqov」，是說**人心像雅各一樣，彎彎曲曲、善於欺騙，包括欺騙自己**。','**{H605}**（anush，無法醫治）：這個字原指**重病、絕症**，出現在十五章十八節「我的傷痕無法醫治」。**先知的傷無法醫治，人心也無法醫治。**可是下面十四節先知禱告：**求你醫治我**。'],
exp=['九節是**整卷書最有名的一句話之一**：人心比萬物都詭詐，是無法醫治的，誰能識透呢？「詭詐」這個字，與雅各同字根，意思是**彎彎曲曲、善於欺騙**。最可怕的是，人心最會欺騙的對象，**是自己**：我們常常以為自己動機純正，其實自己也看不透。','請留意這句話的位置：它**緊接在兩棵樹之後**。五至八節說：倚靠人的受咒詛，倚靠神的有福。九節接著問：**為什麼人會倚靠錯誤？因為人心詭詐**。我們不是**看不見**這兩條路，而是**心會騙我們走錯的那一條**。','這句話常被用作「人性本惡」的證據。我們要小心：**這節話的主要用意，是警告我們不要相信自己的心**，而不是在建立一套人性論。更重要的是它**後面的答案**：十節神說「我—耶和華是鑒察人心的」。**我們看不透自己的心，可是神看得透。**']),
dict(a=10,z=11,star=3,
lit='「我耶和華是鑒察人心、試驗人肺腑的，要照各人的行為，照他所做事的果子報應他。那不按公義得財的，好像鷓鴣孵不是自己下的蛋；到了人生的一半，財富要離開他，他的終局成為愚頑人。」',
key=[('鑒察','H2713','khoqer','探究、鑒察'),('試驗','H974','bokhen','試驗、檢驗'),('肺腑','H3629','kelayot','腎、內心深處'),('鷓鴣','H7124','qore','鷓鴣'),('財富','H6239','osher','財富'),('終局','H319','akharito','結局'),('愚頑人','H5036','naval','愚頑、愚昧')],
gram=['**{H3629}**（kilyah，腎）：古人以腎為**內心深處的情感與良心**，如詩篇七篇九節「鑒察人心腑」。「試驗肺腑」，是神**探測我們最深、連自己都沒有察覺的地方**。','**{H5036}**（naval，愚頑）：這個字與**拿八**（撒上二十五章）同字根。「愚頑人」在聖經裡，不是智商低，而是**心中沒有神**（詩十四篇一節）。'],
exp=['十節是九節的**答案**：**我—耶和華是鑒察人心、試驗人肺腑的。**人心詭詐，連自己也看不透，可是神看得透。這句話有**兩面**：對自欺的人，是警告；對受冤屈的人，是安慰。因為**神知道真相**。','十一節是一個**很有趣的比喻**：不按公義得財的人，像鷓鴣孵不是自己下的蛋。古人相信鷓鴣會偷別的鳥的蛋來孵，可是小鳥長大就飛走了。**不義之財，得到的時候像是自己的，最後會離開。**這是第九、十節的**具體例子**：人心詭詐，所以會用不義的方法得財。','請留意最後一句：**他的終局成為愚頑人**。聖經說的愚頑，不是不聰明，而是**活著的時候，沒有把神放在眼中**。這是一個很重的詞，可是**重點不是定罪，而是警告**：趁還有時間，轉向神。']),
dict(a=12,z=13,star=3,
lit='「我們的聖所，是從起初就安置在高處的榮耀寶座。耶和華啊，以色列的盼望，凡離棄你的都要蒙羞；離開我的，他們的名字要寫在地上，因為他們離棄了耶和華，那活水的泉源。」',
key=[('寶座','H3678','kise','寶座'),('高處','H4791','marom','高處'),('聖所','H4720','miqdashenu','聖所'),('盼望','H4723','miqveh','盼望、水池'),('蒙羞','H954','yevoshu','羞愧'),('寫','H3789','yikatevu','寫'),('泉源','H4726','meqor','泉源')],
gram=['**{H4723}**（miqveh，盼望）：這個字再次出現（十四章八節），雙關**「盼望／水池」**。耶和華是以色列的**盼望，也是水池**。**{H4726}**（meqor，泉源）：「活水的泉源」是耶利米書二章十三節的**開篇指控**：離棄活水泉源、自鑿破裂的池子。這裡再次呼應：**二章的指控，在十七章成了結論**。','**{H3789}**（katav，寫）：「名字寫在地上」與一節「罪刻在心版上」是**強烈的對比**：**罪刻在金鋼石上，名字卻寫在塵土裡**，風一吹就沒有了。'],
exp=['十二節忽然轉了一個方向：我們的聖所，是從起初就安置在高處的榮耀寶座。這是一句**敬拜的宣告**，在一連串審判與診斷之後，先知**抬起頭來**。**人心詭詐，可是神的寶座穩固**。這個轉向，是整章的**樞紐**。','十三節的比喻特別強：**離棄神的人，名字寫在地上；他們離棄的，是活水的泉源**。「寫在地上」，意思是風一吹就沒有了；而一節的罪，卻是用金鋼石**刻**的。這個對比：**罪刻得很深，而人的名字，卻寫得很淺。**這提醒我們：只有**回到神**，我們的名字才不會被抹去（路十章二十節）。','請記得：這裡「活水的泉源」是回應**二章十三節**。耶利米書的前半，是從「離棄活水泉源」開始，十七章**再次回到這個主題**。這是整卷書的一個**中心軸線**：**我們離開了泉源，就要去鑿破裂的池子。**']),
dict(a=14,z=15,star=3,
lit='「耶和華啊，求你醫治我，我就得醫治；拯救我，我就得救；因為你是我所讚美的。看哪，他們對我說：耶和華的話在哪裡呢？讓它來吧！」',
key=[('讚美','H8416','tehillati','我所讚美的'),('哪裡','H346','ayyeh','在哪裡'),('話','H1697','devar','話語')],
gram=['**{H8416}**（tehillah，讚美）：「你是我所讚美的」，原文是「你是我的**讚美**」：神不只是被讚美的對象，**祂就是我讚美的內容**。這是整個先知告白中，**最美的一句**。','**{H346}**（ayyeh，哪裡）：這是**嘲笑的問句**，也出現在二章六、八節「耶和華在哪裡」。**這次，是人嘲笑先知：你說的話，在哪裡？**'],
exp=['十四節是整章**最美的禱告**：耶和華啊，求你醫治我，我就得醫治；拯救我，我就得救。請看這個禱告的**邏輯**：九節說人心無法醫治，十四節先知就**向那位能醫治的神求**。**人心無法自己治好，可是神能。**這是整個福音的方向。','請注意：先知說「你是我所讚美的」。**他不是先得到醫治再讚美，而是在還沒有得到醫治的時候，就已經說：祢是我的讚美**。這是一種**預先的信靠**。','十五節是人的嘲笑：耶和華的話在哪裡呢？讓它來吧！這是**每一個傳講神話的人**都會聽到的一句話：你說的審判，怎麼還沒有來？這是先知的**日常處境**。**嘲笑，是忠心的代價。**']),
dict(a=16,z=18,star=2,
lit='「至於我，我沒有急忙離開牧養的職分來跟從你，也沒有渴望那災禍的日子；你知道，我口中所出的，都在你面前。不要使我因你驚恐；在災禍的日子，你是我的避難所。願那些逼迫我的人蒙羞，卻不要使我蒙羞；使他們驚惶，卻不要使我驚惶；使災禍的日子臨到他們，用加倍的破壞毀壞他們。」',
key=[('牧人','H7462','mero-ah','牧養'),('驚恐','H4288','limkhittah','驚嚇、恐怖'),('避難所','H4268','makhsi','我的避難處'),('逼迫','H7291','rodfai','逼迫我的人'),('加倍','H4932','mishneh','雙倍'),('毀壞','H7670','shiberon','破碎')],
gram=['**{H4268}**（makhseh，避難所）：這個字與十六章十九節的「避難所」（manus）不同，指**躲雨的地方、庇護所**。先知一再用不同的詞，說同一件事：**神是我的藏身處**。','**{H7291}**（radaf，逼迫）：這個字與十五章十五節「逼迫我的人」同字根。先知的**第四次告白**（十七章十二至十八節），也是以「逼迫」作主題。'],
exp=['十六至十八節是先知**第四次告白**（十一章十八節至十二章六節、十五章十至二十一節之後）。他說了三件事：第一，**我沒有急忙離開牧養的職分**；第二，**我沒有渴望那災禍的日子**；第三，**我口中所出的，都在你面前**。這是**一個忠心人的自白**：我沒有自己想要這樣，我只是照你說的說。','然後是十七節的禱告：不要使我因你驚恐，在災禍的日子，你是我的避難所。**先知說：我怕的不是敵人，我怕的是「因你而驚恐」。**這是一個很深的禱告：**不要讓我成為被你嚇到的人，而要讓我成為在你裡面得安慰的人**。','十八節是**咒詛詩**的一種：願逼迫我的蒙羞，使他們驚惶。我們要小心讀：這是**先知把報仇的權柄交給神**（參十五章十五節），而新約教我們為逼迫我們的人禱告（太五章四十四節）。**這是真實的禱告，可是不是我們今天的模範。**']),
dict(a=19,z=23,star=3,
lit='「耶和華對我這樣說：你去站在平民的門口，就是猶大君王出入的門，又站在耶路撒冷所有的門口，對他們說：猶大的君王，和猶大眾人，並耶路撒冷的一切居民，凡從這些門進入的，都要聽耶和華的話。耶和華這樣說：你們要小心，不要在安息日擔任何擔子進入耶路撒冷的各門，也不要在安息日從你們的家中擔出擔子，也不要做任何工作；你們要以安息日為聖，正如我吩咐你們列祖的。他們卻不聽從，也不側耳而聽，竟然硬著頸項，不聽也不受教訓。」',
key=[('硬頸項','H6203','orfam','頸項'),('硬','H7185','vayaqshu','使硬'),('教訓','H4148','musar','管教、教訓'),('側耳','H5186','hittu','側耳、傾斜'),('工作','H4399','melakhah','工作'),('聖','H6942','vekidashtem','使成聖')],
gram=['**{H4399}**（melakhah，工作）：這個字是安息日誡命的**關鍵字**（出二十章十節）：不可做任何「melakhah」。**不是「不可動」，而是不可「營生」。**','**{H6942}**（qadash，聖）：「以安息日為聖」，是把這一天**分別出來**，屬於神。這是**一個時間的分別為聖**。'],
exp=['十九至二十七節是這一章的**第五段**，也是最容易被忽略的一段：安息日。先知被叫去站在**城門口**，對所有進出的人說話。為什麼是城門？因為城門是**人來人往、做買賣、搬運貨物**的地方。神在**最忙碌的地方**，說：停下來。','這段與前面的關係是什麼？前四節說：罪刻在心版上；五至八節說：倚靠人的受咒詛；九至十三節說：人心詭詐；十四至十八節是先知的禱告。**然後神給了一個很具體、很日常的出路：守安息日。**這不是一條規矩，而是一個**「把重量放回神身上」的每週操練**。','安息日在這裡是**對「倚靠」的實際訓練**：一週有一天，我什麼都不做，**因為我相信神會照顧我**。**不守安息日的人，其實是在說：我必須靠自己，世界才轉得動。**這就是五節「倚靠血肉」的**日常版本**。','我們要小心：這是對當時猶大的命令，新約對安息日有新的理解（可二章二十七節；西二章十六至十七節；來四章）。這一段**不是**要我們照搬舊約的規條，而是**看見安息背後的屬靈原則**：**停下來，承認神是神。**']),
dict(a=24,z=27,star=3,
lit='「你們若留意聽從我，這是耶和華說的，在安息日不擔擔子進入這城的各門，只以安息日為聖，不做任何工；那時，就有坐大衛寶座的君王和首領，坐車騎馬，進入這城的各門，他們和猶大人、耶路撒冷的居民，這城就要存到永遠。有人要從猶大各城邑和耶路撒冷四圍，從便雅憫地、低地、山地和南地而來，帶燔祭、平安祭、素祭、乳香和感謝祭，到耶和華的殿去。你們若不聽從我，不以安息日為聖，仍然在安息日擔擔子，進入耶路撒冷的各門，我必在各門中點火，這火要燒毀耶路撒冷的宮殿，不能熄滅。」',
key=[('大衛','H1732','david','大衛'),('燔祭','H5930','olah','燔祭'),('乳香','H3828','levonah','乳香'),('感謝祭','H8426','todah','感謝'),('點火','H3341','vehitsatti','點燃'),('宮殿','H759','armenot','宮殿'),('熄滅','H3518','tikhbeh','熄滅')],
gram=['**{H8426}**（todah，感謝）：「感謝祭」是**主動、自願的感恩**，與贖罪祭不同。這是十七章結尾的**畫面**：一個**感恩的群體**，帶著感謝祭，湧向神的殿。','**{H3341}**（yatsat，點燃）：「點火」是十七章四節「怒中起火」的**回應**：**第一段說火要燒，最後一段又說火要燒**，整章以**火**開始，也以火結束。'],
exp=['二十四至二十六節是一幅**極美的畫面**：如果他們聽從，守安息日，大衛的寶座永不斷絕；人們從猶大各地、從便雅憫、從低地、山地、南地，帶著燔祭、平安祭、素祭、乳香和**感謝祭**，湧向神的殿。**這是一個復興的畫面。**','請留意這個**順序**：不是「先有復興，才守安息」，而是「先守安息，才有復興」。**復興的鑰匙，不是更多的活動，而是更多的停下來。**安息，是信靠的實踐；信靠，是復興的根。','二十七節是**相反的結果**：不守安息日，就要有火，燒毀耶路撒冷的宮殿，不能熄滅。全章的結構因此**首尾呼應**：一至四節說火，二十七節也說火。**中間的整個旅程：罪、倚靠、人心、禱告、安息，都是在回答同一個問題：我要怎樣躲過這火？答案：回到神，扎根在水旁。**']),
]
